var RAISES = [
  "a is == 1",
  "a is not == 1",
  "a is != 1",
  "a is not != 1",
  "a is < 1",
  "a is not < 1",
  "a is <= 1",
  "a is not <= 1",
  "a is > 1",
  "a is not > 1",
  "a is >= 1",
  "a is not >= 1"
];

var OPS = { eq: '==', equalto: '==', ne: '!=', lt: '<', lessthan: '<', le: '<=', gt: '>', greaterthan: '>', ge: '>=' };

function ifs(x) {
  return '{% if ' + x + ' %}Y{% else %}N{% endif %}';
}

function copy(v) {
  return JSON.parse(JSON.stringify(v));
}

function flip(out) {
  return out === 'Y' ? 'N' : (out === 'N' ? 'Y' : out);
}

/*!
 * The locals of a matrix pair: `a` takes value i and `b` value j; "$missing"
 * leaves the name unset.
 */
function pairLocals(i, j) {
  var l = {};
  if (VALUES[i][1] !== '$missing') { l.a = copy(VALUES[i][1]); }
  if (VALUES[j][1] !== '$missing') { l.b = copy(VALUES[j][1]); }
  return l;
}

var syncInst = new Engine({ autoescape: false }), syncFns = {};

function renderSync(tpl, locals) {
  try {
    syncFns[tpl] = syncFns[tpl] || syncInst.compile(tpl);
    return syncFns[tpl](locals);
  } catch (e) {
    return 'THROW ' + e.message;
  }
}

/*!
 * The expected output of a job: the reference's, or for an "o" cell what the
 * operator twin renders (negated for `is not`).
 */
function wantOf(job) {
  if (job.want !== 'o') { return job.want; }
  var out = renderSync(job.twin, job.locals());
  return job.negate ? flip(out) : out;
}

function asyncInstance(templates) {
  var loader = {
    async: true,
    resolve: function (to) { return to; },
    load: function (id, cb) {
      if (cb) { setImmediate(function () { cb(null, templates[id]); }); return undefined; }
      return templates[id];
    }
  };
  return new Engine({ autoescape: false, loader: loader });
}

/*!
 * Every job, rendered on the sync path: `diffs` names each output that
 * differs from the expectation.
 */
function syncDiffs(jobs) {
  var diffs = [];
  jobs.forEach(function (job) {
    var out = renderSync(job.tpl, job.locals()), want = wantOf(job);
    if (out !== want) { diffs.push(job.id + ': ' + out + ' (expected ' + want + ')'); }
  });
  return diffs;
}

/*!
 * Every job, rendered one after the other on the async render path.
 */
function asyncDiffs(jobs, done) {
  var templates = {}, names = {}, n = 0, diffs = [], inst, i = 0;
  jobs.forEach(function (job) {
    if (!names.hasOwnProperty(job.tpl)) { names[job.tpl] = '/t' + (n += 1); templates[names[job.tpl]] = job.tpl; }
  });
  inst = asyncInstance(templates);
  function next() {
    var job = jobs[i];
    if (!job) {
      try { expect(diffs).to.eql([]); } catch (e) { return done(e); }
      return done();
    }
    i += 1;
    inst.renderFile(names[job.tpl], job.locals(), function (err, out) {
      var want = wantOf(job);
      out = err ? 'THROW ' + err.message : out;
      if (out !== want) { diffs.push(job.id + ': ' + out + ' (expected ' + want + ')'); }
      next();
    });
  }
  next();
}

/*!
 * One job per test name and pair: `form` is "bare" (`a is lt b`), "not"
 * (`a is not lt b`) or "paren" (`a is lt(b)`).
 */
function matrixJobs(form, rowsByName) {
  var jobs = [];
  Object.keys(rowsByName).forEach(function (name) {
    var x = form === 'not' ? 'a is not ' + name + ' b' : (form === 'paren' ? 'a is ' + name + '(b)' : 'a is ' + name + ' b');
    VALUES.forEach(function (a, i) {
      VALUES.forEach(function (b, j) {
        jobs.push({ id: form + ':' + name + ':' + a[0] + ':' + b[0], tpl: ifs(x), twin: ifs('a ' + OPS[name] + ' b'),
          negate: form === 'not', want: rowsByName[name][i].charAt(j), locals: function () { return pairLocals(i, j); } });
      });
    });
  });
  return jobs;
}

function caseJobs(cases) {
  return cases.map(function (c) {
    return { id: c[0], tpl: ifs(c[1]), twin: c[4] === null ? null : ifs(c[4]), negate: false, want: c[3],
      locals: function () { return copy(c[2]); } };
  });
}

describe('@rhinostone/swig-jinja2 — comparison tests, checked against Jinja2 3.1.6', function () {

  it('the nine comparison tests over every pair of 15 values', function () {
    expect(syncDiffs(matrixJobs('bare', BARE))).to.eql([]);
  });

  it('`is not` with each comparison test over every pair of 15 values', function () {
    expect(syncDiffs(matrixJobs('not', NOT))).to.eql([]);
  });

  it('each comparison test with a parenthesized argument over every pair of 15 values', function () {
    expect(syncDiffs(matrixJobs('paren', PAREN))).to.eql([]);
  });

  it('literal arguments, binding shapes and the `"<name>" is test` guard', function () {
    expect(syncDiffs(caseJobs(CASES))).to.eql([]);
  });

  it('a symbol after `is` does not compile, as in Jinja2', function () {
    RAISES.forEach(function (x) {
      expect(function () { new Engine().compile(ifs(x)); }).to.throwError(/after "is"/);
    });
  });

  it('each comparison test renders what its operator renders, over every pair of 15 values', function () {
    var diffs = [];
    Object.keys(OPS).forEach(function (name) {
      VALUES.forEach(function (a, i) {
        VALUES.forEach(function (b, j) {
          var op = renderSync(ifs('a ' + OPS[name] + ' b'), pairLocals(i, j)),
            test = renderSync(ifs('a is ' + name + ' b'), pairLocals(i, j)),
            neg = renderSync(ifs('a is not ' + name + ' b'), pairLocals(i, j));
          if (test !== op || neg !== flip(op)) { diffs.push(name + ':' + a[0] + ':' + b[0] + ': ' + test + '/' + neg + ' (operator ' + op + ')'); }
        });
      });
    });
    expect(diffs).to.eql([]);
  });

  describe('on the async render path', function () {

    it('the nine comparison tests over every pair of 15 values', function (done) {
      asyncDiffs(matrixJobs('bare', BARE), done);
    });

    it('`is not` with each comparison test over every pair of 15 values', function (done) {
      asyncDiffs(matrixJobs('not', NOT), done);
    });

    it('each comparison test with a parenthesized argument over every pair of 15 values', function (done) {
      asyncDiffs(matrixJobs('paren', PAREN), done);
    });

    it('literal arguments, binding shapes and the `"<name>" is test` guard', function (done) {
      asyncDiffs(caseJobs(CASES), done);
    });

    it('a symbol after `is` does not compile, as in Jinja2', function (done) {
      var templates = {}, inst, i = 0;
      RAISES.forEach(function (x, k) { templates['/r' + k] = ifs(x); });
      inst = asyncInstance(templates);
      function next() {
        if (i === RAISES.length) { return done(); }
        i += 1;
        inst.renderFile('/r' + (i - 1), {}, function (err) {
          try { expect(err && err.message).to.match(/after "is"/); } catch (e) { return done(e); }
          next();
        });
      }
      next();
    });
  });
});
